    </style>
    <style>
        :root{--tech-cyan:#21dcff;--tech-violet:#7956ff;--tech-card:#0b111c;--mx:50%;--my:50%}
        body{background:radial-gradient(circle at 75% 5%,rgba(33,220,255,.09),transparent 26%),radial-gradient(circle at 15% 45%,rgba(121,86,255,.09),transparent 28%),#05070c;overflow-x:hidden}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.22;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(to bottom,#000,transparent 88%)}
        .hero{min-height:520px;position:relative;isolation:isolate;overflow:hidden;border-radius:0 0 56px 56px;background:linear-gradient(100deg,rgba(3,6,12,.96),rgba(5,14,24,.72)),var(--hero-image) center/cover,#07111e}
        .hero:before{content:"";position:absolute;width:520px;height:520px;border:1px solid rgba(33,220,255,.22);border-radius:50%;left:-100px;top:-190px;box-shadow:0 0 120px rgba(33,220,255,.12),inset 0 0 90px rgba(121,86,255,.08);animation:orbit 14s linear infinite}
        .hero:after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,transparent 49.8%,rgba(33,220,255,.08) 50%,transparent 50.2%),linear-gradient(transparent 49.8%,rgba(33,220,255,.05) 50%,transparent 50.2%);background-size:90px 90px;transform:perspective(600px) rotateX(64deg) scale(1.8) translateY(33%);transform-origin:bottom;opacity:.55}
        .hero-content{position:relative;z-index:2;display:grid;grid-template-columns:1.2fr .8fr;align-items:center;min-height:450px}
        .hero-copy{max-width:720px}.hero-kicker{display:inline-flex;align-items:center;gap:9px;padding:8px 13px;border:1px solid rgba(33,220,255,.32);border-radius:999px;background:rgba(33,220,255,.07);color:var(--tech-cyan);font-size:12px;font-weight:900;letter-spacing:.08em}.hero h1{font-size:clamp(48px,8vw,100px);letter-spacing:-.05em;line-height:.95;margin:22px 0;background:linear-gradient(135deg,#fff 18%,#75eaff 52%,#947dff);-webkit-background-clip:text;color:transparent;filter:drop-shadow(0 16px 40px rgba(33,220,255,.18))}.hero p{font-size:clamp(15px,2vw,20px);line-height:1.9}.hero-device{justify-self:center;width:min(330px,32vw);aspect-ratio:.62;border-radius:42px;border:2px solid rgba(255,255,255,.18);background:linear-gradient(145deg,#202b3a,#05080d 55%);transform:perspective(900px) rotateY(-22deg) rotateX(8deg);box-shadow:-35px 35px 80px rgba(0,0,0,.65),0 0 70px rgba(33,220,255,.15),inset 0 0 0 8px #080d14;position:relative;animation:deviceFloat 5s ease-in-out infinite}.hero-device:before{content:"";position:absolute;inset:12px;border-radius:31px;background:radial-gradient(circle at 65% 22%,rgba(33,220,255,.75),transparent 15%),radial-gradient(circle at 35% 62%,rgba(121,86,255,.75),transparent 22%),linear-gradient(145deg,#081723,#110c27)}.hero-device:after{content:"";position:absolute;width:34%;height:20px;border-radius:0 0 14px 14px;background:#030507;top:12px;left:33%}
        .filters{border-color:rgba(33,220,255,.16);background:rgba(8,13,22,.76);backdrop-filter:blur(24px);box-shadow:0 24px 80px rgba(0,0,0,.28);margin-top:-34px;z-index:8}.filters input,.filters select{transition:.25s;border-color:#22354a}.filters input:focus,.filters select:focus{outline:0;border-color:var(--tech-cyan);box-shadow:0 0 0 3px rgba(33,220,255,.1)}.filters button{background:linear-gradient(135deg,var(--tech-cyan),#4ca9ff 52%,var(--tech-violet));box-shadow:0 10px 28px rgba(33,220,255,.2);transition:.25s}.filters button:hover{transform:translateY(-2px);box-shadow:0 16px 36px rgba(33,220,255,.32)}
        .cats{padding:12px 2px 20px}.chip{background:rgba(12,19,31,.75);backdrop-filter:blur(14px);transition:.25s}.chip:hover{color:#061019;background:var(--tech-cyan);border-color:var(--tech-cyan);transform:translateY(-3px);box-shadow:0 10px 28px rgba(33,220,255,.24)}
        .grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;perspective:1400px}.card{--rx:0deg;--ry:0deg;--lift:0px;overflow:visible;background:linear-gradient(145deg,rgba(16,25,40,.96),rgba(6,9,15,.98));border:1px solid rgba(112,176,214,.18);border-radius:30px;transform-style:preserve-3d;transform:perspective(1100px) rotateX(var(--rx)) rotateY(var(--ry)) translateY(var(--lift));transition:transform .16s ease-out,border-color .3s,box-shadow .3s;box-shadow:0 26px 55px rgba(0,0,0,.32);opacity:0;translate:0 28px}.card.is-visible{opacity:1;translate:0 0;transition:opacity .65s ease,translate .65s ease,transform .16s ease-out,border-color .3s,box-shadow .3s}.card:hover{--lift:-10px;border-color:rgba(33,220,255,.55);box-shadow:0 38px 85px rgba(0,0,0,.5),0 0 40px rgba(33,220,255,.12)}.card:before{content:"";position:absolute;inset:-1px;border-radius:inherit;pointer-events:none;background:radial-gradient(320px circle at var(--mx) var(--my),rgba(33,220,255,.2),transparent 48%);opacity:0;transition:.3s}.card:hover:before{opacity:1}.device-visual{height:330px;position:relative;display:grid;place-items:center;overflow:hidden;border-radius:29px 29px 8px 8px;background:radial-gradient(circle at 50% 42%,rgba(33,220,255,.12),transparent 35%),linear-gradient(150deg,#0e1826,#070a10);transform:translateZ(28px)}.device-visual:before{content:"";position:absolute;width:230px;height:230px;border:1px solid rgba(33,220,255,.22);border-radius:50%;animation:spin 12s linear infinite;box-shadow:0 0 50px rgba(33,220,255,.08)}.device-visual:after{content:"";position:absolute;width:170px;height:170px;border:1px dashed rgba(121,86,255,.35);border-radius:50%;animation:spin 9s linear reverse infinite}.card .device-image{position:relative;z-index:2;width:88%;height:88%;object-fit:contain;background:transparent;filter:drop-shadow(0 28px 24px rgba(0,0,0,.55));transition:.45s cubic-bezier(.2,.8,.2,1)}.card:hover .device-image{transform:translateY(-8px) scale(1.05) rotate(-2deg)}.body{position:relative;z-index:3;padding:22px;transform:translateZ(18px)}.card h2{font-size:23px}.price{font-size:28px;background:linear-gradient(90deg,#fff,var(--tech-cyan));-webkit-background-clip:text;color:transparent}.stock{margin-top:6px}.actions a,.actions button{border-radius:14px;transition:.25s}.details{background:linear-gradient(135deg,var(--tech-cyan),#5bb4ff);box-shadow:0 10px 24px rgba(33,220,255,.16)}.actions a:hover,.actions button:hover{transform:translateY(-2px)}
        @keyframes orbit{to{transform:rotate(360deg)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes deviceFloat{50%{transform:perspective(900px) rotateY(-18deg) rotateX(5deg) translateY(-16px)}}
        @media(max-width:980px){.hero-content{grid-template-columns:1fr}.hero-device{display:none}.grid{grid-template-columns:repeat(2,1fr)}}
        @media(max-width:580px){.hero{min-height:390px;border-radius:0 0 34px 34px}.hero-content{min-height:330px}.hero h1{font-size:52px}.filters{margin-top:-22px}.grid{grid-template-columns:1fr}.card{display:block}.device-visual{height:300px}.card .device-image{height:88%}}
        .hero-webgl{justify-self:center;width:min(460px,40vw);height:440px;position:relative;filter:drop-shadow(0 35px 55px rgba(0,0,0,.65))}.hero-webgl canvas{display:block;width:100%!important;height:100%!important;cursor:grab}.hero-webgl canvas:active{cursor:grabbing}.webgl-fallback{position:absolute;inset:20%;display:grid;place-items:center;border:1px solid rgba(33,220,255,.2);border-radius:50%;color:var(--tech-cyan)}
        @media(max-width:980px){.hero-webgl{position:absolute;left:-80px;opacity:.32;width:380px;pointer-events:none}.hero-copy{position:relative;z-index:2}}
        @media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition-duration:.01ms!important}.card{opacity:1;translate:none}}
    </style>
</head>
<body>
<header class="hero" style="--hero-image:url('{{ $shop->banner ? asset($shop->banner) : '' }}')"><div class="wrap hero-content"><div class="hero-copy"><div class="hero-kicker">● الجيل الجديد من التسوق التقني</div><h1>{{ $shop->name }}</h1><p>{{ $shop->description ?: 'اكتشف أحدث الأجهزة، اختر مواصفاتك بدقة، واطلبها مباشرة من المتجر.' }}</p></div><div class="hero-webgl" id="electronicsWebgl" aria-label="مجسم هاتف ثلاثي الأبعاد تفاعلي"><div class="webgl-fallback">3D</div></div></div></header>
<main class="wrap">
    <form class="filters" method="GET">
        <input name="q" value="{{ request('q') }}" placeholder="ابحث عن جهاز أو موديل...">
        <select name="brand"><option value="">كل الماركات</option>@foreach($brands as $brand)<option @selected(request('brand')===$brand)>{{ $brand }}</option>@endforeach</select>
        <select name="storage"><option value="">كل السعات</option>@foreach($storages as $storage)<option @selected(request('storage')===$storage)>{{ $storage }}</option>@endforeach</select>
        <select name="condition"><option value="">جديد ومستعمل</option><option @selected(request('condition')==='جديد')>جديد</option><option @selected(request('condition')==='مستعمل')>مستعمل</option></select>
        <input type="number" name="min_price" value="{{ request('min_price') }}" placeholder="أقل سعر">
        <input type="number" name="max_price" value="{{ request('max_price') }}" placeholder="أعلى سعر">
        <button>تصفية</button>
    </form>
    <nav class="cats"><a class="chip" href="{{ route('electronics.store',$shop) }}">الكل</a>@foreach($categories as $category)<a class="chip" href="{{ route('electronics.store',[$shop,'category'=>$category->id]) }}">{{ $category->localized('name') }}</a>@endforeach</nav>
    <section class="grid">
        @forelse($products as $product)
            @php
                $attrs = $product->catalog_attributes ?? [];
                $available = $product->variants->where('quantity', '>', 0);
                $from = $available->min(fn ($variant) => (float) ($variant->price ?? $product->discount_price ?? $product->price));
                $compareData = ['id' => $product->id, 'name' => $product->localized('name'), 'brand' => data_get($attrs, 'brand'), 'model' => data_get($attrs, 'model'), 'network' => data_get($attrs, 'network'), 'screen' => data_get($attrs, 'screen_size'), 'processor' => data_get($attrs, 'processor'), 'price' => $from];
            @endphp
            @php
                $mainImage = $product->main_image;
                $mainImageUrl = $mainImage
                    ? (\Illuminate\Support\Str::startsWith($mainImage, ['http://', 'https://', 'storage/']) ? asset($mainImage) : asset('storage/'.$mainImage))
                    : asset('images/1.jpg');
            @endphp
            <article class="card" data-tilt data-compare="{{ e(json_encode($compareData, JSON_UNESCAPED_UNICODE)) }}">
                <div class="device-visual"><img class="device-image" src="{{ $mainImageUrl }}" alt="{{ $product->localized('name') }}" loading="lazy"></div>
                <div class="body"><div class="brand">{{ data_get($attrs,'brand') }} · {{ data_get($attrs,'condition') }}</div><h2>{{ $product->localized('name') }}</h2><div class="specs"><span>{{ data_get($attrs,'network') }}</span><span>{{ data_get($attrs,'screen_size') }}</span>@foreach($available->pluck('storage')->filter()->unique()->take(3) as $storage)<span>{{ $storage }}</span>@endforeach</div><div class="price">{{ number_format($from,2) }} ₪</div><div class="stock">{{ $available->sum('quantity') ? 'متوفر الآن' : 'نفدت الخيارات' }}</div><div class="actions"><a class="details" href="{{ route('electronics.product',[$shop,$product]) }}">التفاصيل والشراء</a><button type="button" class="compare">مقارنة</button></div></div>
            </article>
        @empty <div class="empty">لا توجد أجهزة مطابقة للفلاتر.</div> @endforelse
    </section>
    <div class="pagination">{{ $products->links() }}</div>
</main>
<aside class="compare-bar" id="compareBar"><strong>المقارنة</strong><div class="compare-list" id="compareList"></div><button type="button" id="clearCompare">مسح</button></aside>
<script>
const selected=[];const bar=document.getElementById('compareBar'),list=document.getElementById('compareList');
function draw(){bar.classList.toggle('show',selected.length>0);list.innerHTML=selected.map(x=>`<div class="compare-item"><b>${x.name}</b><br>${x.brand||''} ${x.model||''}<br>${x.network||''} · ${x.screen||''}<br>${x.processor||''}<br><b>${Number(x.price).toFixed(2)} ₪</b></div>`).join('')}
document.querySelectorAll('.compare').forEach(btn=>btn.onclick=()=>{const item=JSON.parse(btn.closest('[data-compare]').dataset.compare);if(!selected.some(x=>x.id===item.id)&&selected.length<3)selected.push(item);draw()});document.getElementById('clearCompare').onclick=()=>{selected.length=0;draw()};
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll('[data-tilt]').forEach((card,index)=>{card.style.transitionDelay=`${Math.min(index*70,350)}ms`;observer.observe(card);card.addEventListener('pointermove',event=>{if(matchMedia('(pointer:coarse)').matches)return;const rect=card.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width,y=(event.clientY-rect.top)/rect.height;card.style.setProperty('--ry',`${(x-.5)*10}deg`);card.style.setProperty('--rx',`${(.5-y)*9}deg`);card.style.setProperty('--mx',`${x*100}%`);card.style.setProperty('--my',`${y*100}%`)});card.addEventListener('pointerleave',()=>{card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg')})});
</script>
<script type="module" src="{{ asset('electronics-3d.js') }}?v={{ filemtime(public_path('electronics-3d.js')) }}"></script>
</body></html>
